syntax:
template <typename T> class ClassName { /* general implementation */ };
template <> class ClassName<SpecificType> { /* specialized implementation for SpecificType */ };

// For function templates:
template <typename T> void function(T arg) { /* general implementation */ }
template <> void function<SpecificType>(SpecificType arg) { /* specialized implementation for SpecificType */ }

code_example:
#include <iostream>

// General template class
template <typename T>
class Calculator {
public:
    void compute() {
        std::cout << "Generic calculation for type." << std::endl;
    }
};

// Specialization for int type
template <>
class Calculator<int> {
public:
    void compute() {
        std::cout << "Specialized calculation for int." << std::endl;
    }
};

int main() {
    Calculator<double> calcDouble;
    calcDouble.compute(); // Uses general template
    Calculator<int> calcInt;
    calcInt.compute(); // Uses specialized template
    return 0;
}
